// pubspec.yaml: google_maps_flutter: ^2.7.0
import 'package:google_maps_flutter/google_maps_flutter.dart';

class MapScreen extends StatefulWidget {
  const MapScreen({super.key});
  @override State<MapScreen> createState() => _MapScreenState();
}

class _MapScreenState extends State<MapScreen> {
  GoogleMapController? _controller;
  final _markers = <MarkerId, Marker>{};
  final _polylines = <PolylineId, Polyline>{};

  static const _initial = CameraPosition(target: LatLng(12.9716, 77.5946), zoom: 12);

  @override
  Widget build(BuildContext context) {
    return GoogleMap(
      initialCameraPosition: _initial,
      onMapCreated: (c) => _controller = c,
      markers: _markers.values.toSet(),
      polylines: _polylines.values.toSet(),
      myLocationEnabled: true,
      myLocationButtonEnabled: true,
      zoomControlsEnabled: false,
      onTap: _addPin,
    );
  }

  void _addPin(LatLng p) {
    final id = MarkerId('pin_${DateTime.now().microsecondsSinceEpoch}');
    setState(() => _markers[id] = Marker(
      markerId: id, position: p,
      infoWindow: InfoWindow(title: '${p.latitude.toStringAsFixed(3)}, ${p.longitude.toStringAsFixed(3)}'),
      onTap: () async {
        await _controller!.animateCamera(CameraUpdate.newLatLngZoom(p, 16));
      },
    ));
  }

  Future<void> _drawRoute(List<LatLng> points) async {
    const id = PolylineId('route');
    setState(() => _polylines[id] = Polyline(
      polylineId: id, color: Colors.blue, width: 5, points: points,
    ));
    // Fit bounds
    final bounds = LatLngBounds(
      southwest: LatLng(points.map((p) => p.latitude).reduce(min),
                        points.map((p) => p.longitude).reduce(min)),
      northeast: LatLng(points.map((p) => p.latitude).reduce(max),
                        points.map((p) => p.longitude).reduce(max)),
    );
    await _controller!.animateCamera(CameraUpdate.newLatLngBounds(bounds, 60));
  }

  @override void dispose() { _controller?.dispose(); super.dispose(); }
}
